theorem exists_numbers_in_interval (n : ℕ) (hn : 100 ≤ n) :
    ∃ l : ℕ, n + 4 * l ≤ 2 * l ^ 2 ∧ 2 * l ^ 2 + 4 * l ≤ 2 * n  := by
  have hn' : 1 ≤ Nat.sqrt (n + 1) := Nat.le_sqrt (by linarith);
  have h1 := Nat.sqrt_le' (n + 1);
  have h2 := Nat.succ_le_succ_sqrt' (n + 1);
  have h3 : 10 ≤ (n + 1).sqrt := Nat.le_sqrt (by linarith);
  rw [← Nat.sub_add_cancel hn'] at h1 h2 h3;
  use (n + 1).sqrt - 1;
  calc n + 4 * l ≤ (l ^ 2 + 4 * l + 2) + 4 * l := by linarith [h2];
  linarith [h3];

